4class Board {
5
6    public:
7        // count variable
8        int count = 0;
9        char board[9] = { ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ' };
10
11        void print_board() {
12            cout << " " << board[0] << " | " << board[1] << " | " << board[2] << endl;
13            cout << "-----------" << endl;
14            cout << " " << board[3] << " | " << board[4] << " | " << board[5] << endl;
15            cout << "-----------" << endl;
16            cout << " " << board[6] << " | " << board[7] << " | " << board[8] << endl;
17        }
18
19        bool update_board(int position, char type) {
20
21            // if a player selects position n, n-1 index should be updated
22            // if the position is not already filled, update the board
23            if (board[position - 1] == ' ') {
24                board[position - 1] = type;
25
26                // increase the value of count by 1
27                count++;
28                return true;
29            }
30
31            // if the position is already filled, ask user to select another position
32            else {
33                cout << "Position already selected. Select another position.";
34                return false;
35            }
36        }
37
38        // if all variables are selected and there is no winner, it's draw
39        // returning true if it's draw
40        bool check_draw() {
41
42            // check if count == 9
43            if (count == 9) {
44                return true;
45            } 
46            else {
47                return false;
48            }
49        }
50
51        // if three symbols appears in a row, returning true
52        bool check_winner(char type) {
53            if ((board[0] == type && board[1] == type && board[2] == type)
54                    || (board[3] == type && board[4] == type && board[5] == type)
55                    || (board[6] == type && board[7] == type && board[8] == type)
56                    || (board[0] == type && board[3] == type && board[6] == type)
57                    || (board[1] == type && board[4] == type && board[7] == type)
58                    || (board[2] == type && board[5] == type && board[8] == type)
59                    || (board[0] == type && board[4] == type && board[8] == type)
60                    || (board[2] == type && board[4] == type && board[6] == type)) {
61                return true;
62            }
63
64            else {
65                return false;
66            }
67
68        }
69};
