71class Player {
72    public:
73        string name;
74        char type;
75
76        // function to select the player type and name
77        void set_info(char type) {
78
79            // player type is 'X' if parameter is 'X' or 'x'            
80            if (type == 'X' || type == 'x') {
81
82                // set member variable to 'X'
83                this->type = 'X';
84
85                // get player name
86                cout << "Player selecting " << this->type << ", enter your name: ";
87                getline(cin, name);
88            }
89
90            // player type is 'O' if parameter is any other character 
91            else {
92                this->type = 'O';
93                cout << "Player selecting " << this->type << ", enter your name: ";
94                getline(cin, name);
95            }
96        }
97};
