99class Game {   
100    public:
101
102        Board board;
103
104        Player player1;
105        Player player2;
106        Player* current_player;
107        
108        // constructor to set player data
109        Game() {
110            player1.set_info('X');
111            player2.set_info('O');
112            current_player = &player1;
113        }
114
115        void play() {
116            
117            int position;
118
119            // message to prompt player for their position
120            string message = "enter the position (1 - 9): ";
121
122            // using an infinite loop to run the game
123            // we will later add conditions to terminate the loop
124            while (true) {
125
126                cout << current_player->name << " " << message;
127                cin >> position;
128
129                // the update_board() function returns true if
130                // the user selected position is not already filled
131                bool update = board.update_board(position, current_player->type);
132
133                // update the board if the selected position is not filled
134                if (update) {
135
136                    board.print_board();
137                    
138
139                    // call the check_winner() function
140                    bool win_status = board.check_winner(current_player->type);
141                    
142                    // call the check_draw() function
143                    bool draw_status = board.check_draw();
144
145                    // check for winner each time after updating the board
146                    if (win_status) {
147                        cout << current_player->name << " wins!" << endl;
148                        break;
149                    }
150
151                    // check for draw each time after updating the board
152                    else if (draw_status) {
153                        cout << "Game is a draw!" << endl;
154                        break;
155                    }
156
157
158                    // change current player when board is updated
159                    if (current_player == &player1) {
160                        current_player = &player2;
161                    }
162
163                    else {
164                        current_player = &player1;
165                    }
166                }
167            }
168        }
169};
